home = '<div class="wrap"><div class="stat-rail"><div><strong>24 / 7</strong><span>A shared operating direction</span></div><div><strong>One place</strong><span>Rooms, equipment and people connected</span></div><div><strong>Many paths</strong><span>A selected overlap within a wider ecosystem</span></div></div></div>'
home += section('The invitation','Useful overlap, in a place people know.', '<div class="split"><div class="flow"><p class="lead">An Aura civic establishment brings learning, enterprise, creative work, community contribution and practical support into a shared physical setting.</p><p>A room can host a teaching session, a project team, an evening workshop and focused work at different times. Equipment, expertise and relationships can serve several purposes. The people using the place help shape what belongs together.</p><p>This exploration begins with 433 Logan Road, Stones Corner as a candidate location. Its actual room layout and operating arrangements will determine the combinations it can support.</p>'+link('place.html','Examine the place and its evidence →','text-link')+'</div>'+figure('state-library','A real shared learning space: State Library of Victoria, Melbourne. Crisco 1492, CC BY-SA 4.0.')+'</div>')
home += section('A possible daily rhythm','The same space has more than one useful life.', '<p class="lead narrow">Round-the-clock access creates room for different lives and schedules. Each service chooses its hours, people and support arrangements.</p><div class="day-switch" data-day-switch><button type="button" data-day="morning" aria-pressed="true"><strong>06:00–12:00</strong><span>Learn and begin</span></button><button type="button" data-day="afternoon" aria-pressed="false"><strong>12:00–18:00</strong><span>Build and connect</span></button><button type="button" data-day="evening" aria-pressed="false"><strong>18:00–00:00</strong><span>Make and gather</span></button><button type="button" data-day="night" aria-pressed="false"><strong>00:00–06:00</strong><span>Focus and maintain</span></button></div><div class="day-result" data-day-result aria-live="polite"><h3>A morning for learning and introductions</h3><p>Bookable teaching rooms, mentor conversations, personal-Aura introductions and shared desks. Each activity brings an identified host and a workable handover.</p></div><div class="hour-ticks" aria-hidden="true">'+'<i></i>'*24+'</div><div class="hour-labels"><span>00:00</span><span>06:00</span><span>12:00</span><span>18:00</span><span>24:00</span></div>'+link('shared-use.html','Explore the 24/7 shared-use model →','text-link'))
home += section('Choose your way in','A place, a combination, a working scenario.',panels([('Explore the place','Follow the indoor-area evidence, available plans and questions a current survey can answer.','place.html'),('Choose useful overlaps','Select activities and see which rooms, equipment and support could be shared.','overlaps.html'),('Work through the numbers','Change space, opening hours, attendance, staffing and contributions. Save a scenario to discuss.','capacity.html')]),'paper')
home += section('Shared capability, personal authority','People bring their own lives and direction.', '<p class="quote">A shared establishment can support many organisations and many personal journeys. Its common assets create opportunities for people to learn, contribute and choose.</p><div class="split align-top" style="margin-top:3rem"><div class="flow"><h3>Identity, access and belonging</h3><p>The operating direction includes KYC: knowing who is entering a shared facility. Identity verification, activity permissions, room bookings and personal-data sharing each have their own purpose.</p>'+link('access.html','Explore the access model →','text-link')+'</div><div class="flow"><h3>A node in a larger network</h3><p>A Brisbane hub could connect with Dunwich and Minjerribah, Ready SET Co-op, 500 Queens, teaching, resilience and other locally shaped projects. The wider body of work remains open to many locations and combinations.</p>'+link('network.html','Follow the connected projects →','text-link')+'</div></div>')
page('index.html','The invitation','A civic place.<br><em>More possible lives.</em>','An Aura of Intelligence establishment: shared spaces, practical learning and useful overlap, around the clock.','generated-civic-hub-concept',home,eyebrow='Aura of Intelligence · A fair go in the age of intelligence')

building_table=table(['Measure','What the source records','Use in this exploration'],[
 ('5,118 m²','Serviced-office accommodation in the historical comparison for 425 and 433 Logan Road.','An indoor-office reference from the 2017 sale evidence, reproduced in a 2018 valuation report.'),
 ('5,585 m²','Historical combined net lettable area, including café and retail components.','Keep the office, café and separate retail components identifiable.'),
 ('7,266 m²','QPS direct lease area reported in Cushman & Wakefield’s Q4 2023 office report.','A lease-reported measure with a different basis from the historical serviced-office figure.'),
 ('5,000 m²','Editable starting envelope in the capacity calculator.','A rounded planning assumption to replace after current measurement.')])
place=section('433 Logan Road, Stones Corner','Start with the indoor space.', '<div class="split"><div class="flow"><p class="lead">The useful question is how rooms and supporting facilities could serve people through a full week.</p><p>The property was previously described as a serviced-office centre, with a building varying from two to four storeys across the site. Older records place it in Greenslopes. Current research identifies the candidate address as Stones Corner.</p><p>Historical office accommodation offers a starting scale for investigation. A current measured plan will show which rooms, circulation, amenities, access routes and technical areas are available for a selected mix of uses.</p></div><div class="panel"><p class="eyebrow">The current working envelope</p><div class="result-number">5,000 m²</div><p class="result-label">Rounded indoor planning assumption</p><p>Change this figure in the calculator. The model reserves a separately editable proportion for circulation and support.</p>'+link('capacity.html','Open the capacity model →','text-link')+'</div></div>')
place+=section('Read each measure in its own terms','Office area, lease area and usable rooms.',building_table+source_line('Historical comparison: '+link('https://smartinvestor.sorted.org.nz/assets/disclose-documents/28/ba/ec/Valuation-Report.pdf#page=67','m3property valuation report, PDF page 67 / printed page 58')+'. Lease report: '+link('https://assets.cushmanwakefield.com/-/media/cw/marketbeat-pdfs/2023/q4/apac-and-gc/australia--brisbane--fringe-office-q4-2023-updated.pdf?rev=e23762a803d54de6a9206d673ef9feff#page=2','Cushman & Wakefield, Q4 2023, page 2')+'.'),'paper')
place+=section('Plans and a current room inventory','Turn an address into a usable brief.','<div class="split align-top"><div class="flow"><p>The approved plan set associated with Council application <strong>A004942032</strong>, dated 17 September 2018, concerns alterations at the Logan Road offices. Its existing-building outlines help locate the development, while the main interior partition layout still needs a current source.</p><p>A room inventory can record dimensions, doors, daylight, acoustic conditions, power, accessibility and current fit-out. That supports decisions about desks, teaching, private conversations, making, events and service rooms.</p>'+link('https://developmenti.brisbane.qld.gov.au/','Search Development.i for A004942032 →','text-link')+'</div><ol class="numbered-list"><li><div><h3>Measure what is usable</h3><p>Identify the indoor envelope, the shared support areas and the floor-by-floor room schedule.</p></div></li><li><div><h3>Match a selected activity</h3><p>Record the people, privacy, equipment and service arrangements belonging to that room.</p></div></li><li><div><h3>Test the timetable</h3><p>Compare simultaneous occupancy and changeover with weekly bookings and expected visits.</p></div></li></ol></div>')
place+=section('The tenancy context','A large existing commitment is one part of the conversation.','<div class="prose"><p>The Crime and Corruption Commission’s November 2026 report records a 15-year QPS leasing commitment, with a starting annual amount of A$5.8 million indexed at 4%. The premises were subsequently found unsuitable for the intended police use and remained unoccupied.</p><p>A civic proposal needs its own agreed route into the property: the parties involved, available space, term, permitted activities, responsibilities and proposed premises contribution. The financial model keeps that proposed contribution separate from the existing QPS lease reference.</p>'+link('economics.html#lease-reference','Examine the lease-reference arithmetic →','text-link')+'</div>'+source_line(link('https://www.ccc.qld.gov.au/sites/default/files/Docs/Publications/CCC/CCC-Public-Report_Investigation-Sphynx_Nov-2026.pdf','CCC Investigation Sphynx, November 2026, executive summary and timeline')+'.'))
page('place.html','The building','An address to<br><em>work through.</em>','Examine the indoor-area evidence and turn it into a current room and operating brief.','brisbane-story-bridge',place,eyebrow='Candidate location · 433 Logan Road, Stones Corner',tag='Candidate premises · A current measured plan is the next evidence input')

shared=section('168 hours in a week','Plan the place through time.','<div class="split"><div class="flow"><p class="lead">A 24/7 establishment lets people work with schedules that fit learning, care, paid work, creativity and other responsibilities.</p><p>Facility access and programme hours are separate decisions. An evening member might use a booked desk while a host runs a workshop elsewhere. A service provider may offer appointments only during its staffed hours. Maintenance has an allocated place in the calendar.</p><p>The time model therefore records opening hours, bookable availability, actual bookings and changeovers. Each shared asset keeps one identity even when several programmes use it.</p></div>'+figure('generated-night-learning-concept')+'</div>')
shared+=section('An illustrative room week','Different uses, one booking record.','<p class="lead narrow">This example shows how a teaching and project room might change use. It is a discussion sketch, with its staffing and booking arrangements still to develop.</p><div class="calendar-scroll"><div class="calendar-grid"><b>Time</b>'+''.join('<b>'+d+'</b>' for d in ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'])+''.join('<span class="time">'+t+'</span>'+''.join('<span class="'+c+'">'+label+'</span>' for c,label in slots) for t,slots in [
 ('06–12',[('learn','Teaching'),('care','Mentoring'),('learn','Teaching'),('care','Support'),('learn','Teaching'),('create','Making'),('quiet','Booked work')]),
 ('12–18',[('service','Project team'),('learn','Workshop'),('service','Project team'),('learn','Workshop'),('care','Mentoring'),('create','Community'),('service','Upkeep')]),
 ('18–24',[('create','Media'),('learn','Adult learning'),('create','Enterprise'),('learn','Adult learning'),('create','Gathering'),('create','Creative work'),('quiet','Booked work')]),
 ('00–06',[('quiet','Focused work'),('service','Maintenance'),('quiet','Focused work'),('quiet','Focused work'),('service','Maintenance'),('quiet','Focused work'),('quiet','Focused work')])])+'</div></div><p class="table-note">Illustrative activity windows, not a proposed staffing roster or entitlement to a service. Quiet, active and private uses need suitable neighbouring spaces.</p>')
shared+=section('Four parts of shared use','Identity, permission, booking and care for the place.',panels([('Known people and clear access','Agree identity verification, guest arrangements and the permissions needed for each activity.','access.html'),('A timetable that can work','Include setup, pack-down, cleaning, relief and equipment maintenance in bookable hours.','capacity.html#room-time'),('Someone to carry the responsibility','Each activity identifies its host, support route, handover and what happens when the plan changes.','guide.html')]),'paper')
shared+=section('Count different things separately','Membership is a relationship. Occupancy is a moment.',table(['Measure','What it answers'],[('Members','Who belongs to the shared facility or a participating programme?'),('Concurrent occupants','How many people are inside at the same time, including staff, hosts and guests?'),('Desk-hours and room-hours','How much bookable space is available and used across the week?'),('Visits','How many attendances occur, including repeat visits by the same person?'),('People served elsewhere','What support or learning reaches homes, workplaces, schools or other nodes?')])+link('capacity.html','Compare the measures in the calculators →','text-link'))
page('shared-use.html','24/7 shared use','A full week.<br><em>Many rhythms.</em>','Give shared rooms and equipment a useful life across different schedules, activities and organisations.','generated-night-learning-concept',shared)

selector='<div class="programme-selector">'+''.join('<label><input type="checkbox" data-programme="'+p['id']+'"'+(' checked' if p['id'] in ['resilience','women','teaching'] else '')+'><span><strong>'+p['title']+'</strong><small>'+p['description']+'</small></span></label>' for p in programmes)+'</div>'
overlaps=section('Choose a combination','Find the spaces a few activities could share.','<p class="lead narrow">The wider Aura body of work is much larger than one building. Select the activities worth examining together and look for a practical common resource.</p>'+selector+'<div class="overlap-results" data-overlap-result aria-live="polite"><h3>Shared resources to examine</h3><p>Choose activities to compare their room and equipment needs.</p></div><noscript><p class="no-js-note">The programme descriptions remain available. Enable JavaScript to compare selected resource overlaps.</p></noscript>')
overlaps+=section('Begin with the common asset','Overlap has to make life easier.','<div class="split align-top"><div class="flow"><p>A classroom can support teacher development, enterprise learning and volunteer preparation. A media studio can record a skilled installation, produce cultural work and help a young person complete a creative project. A quiet room can host a booked mentoring conversation at another time.</p><p>The shared asset earns its place through those uses. An operator still needs to know what changes between bookings, which equipment remains in the room and who is responsible for returning it ready for the next person.</p></div>'+figure('projects-hero')+'</div>','paper')
overlaps+=section('Activity-specific arrangements','Some overlaps need a different room or timetable.',table(['Activity relationship','What the brief examines'],[('Children, families and adult members','Suitable hosts, activity boundaries, arrivals, departures and use of shared routes.'),('Quiet support and active making','Privacy, acoustic separation, room setup and neighbouring bookings.'),('Computing and public learning','An engineered equipment area connected with an accessible teaching and development space.'),('Everyday events and resilience exercises','Clear exercise material, current information sources and an identified receiving service.'),('Research and general participation','A defined study, qualified partners, appropriate facilities and a distinct participant agreement.')])+ '<div class="callout"><p>The adult Genesis pathway has a separate technical and clinical facility case. Its presence in the archive keeps that option visible; selecting ordinary teaching or support activities does not add a chamber installation to this building brief.</p></div>')
overlaps+=section('A federation in a shared place','Organisations can cooperate through clear arrangements.','<div class="prose"><p>Ready SET Co-op, enterprise programmes, existing providers, technical businesses, creative groups and public partners can each bring a distinct contribution. The host, landlord, asset owner, service operator and financing vehicle may be different participants.</p><p>A useful combination identifies those relationships, the shared costs and the benefits each party receives. Personal Auras remain the property of their people, and cultural authority remains with the relevant people and custodians.</p>'+link('network.html','Explore the wider federation and project connections →','text-link')+'</div>')
page('overlaps.html','Programme overlaps','Where useful<br><em>things meet.</em>','Select a few activities and explore the rooms, equipment and support they might share.','explore-hero',overlaps)

cf=''.join([field('area','Indoor planning envelope · m²',note='Rounded starting assumption. Replace with measured usable indoor space.'),field('supportPercent','Reserved circulation and support · %',maximum=100),field('areaPerPerson','Activity-area allowance · m²/person',step='.5',minimum='.5'),field('desks','Shared desks'),field('openHours','Opening hours per day',step='.5',maximum=24),field('openDays','Opening days per week',maximum=7),field('availabilityPercent','Bookable availability · %',maximum=100,note='After maintenance and unavailable time.'),field('bookingPercent','Use of bookable time · %',maximum=100,note='Scenario utilisation, not measured demand.'),field('hoursPerMember','Average desk-hours per member per week',step='.5',minimum='.5',wide=True)])
capacity=section('Space and time calculator','Work through one shared-desk scenario.','<p class="lead narrow">Start with an editable space envelope and a weekly timetable. The default figures illustrate the arithmetic; a measured floor plan and selected programme mix will replace them.</p>'+toolbar()+tool('capacity','Space, desks and opening hours','Area-based attendance and time-based desk use answer different questions.',cf,'planningPeople','people in the activity-area planning calculation',metric('programmeArea','Area after support reservation')+metric('weeklyHours','Gross opening hours per week')+metric('grossDeskHours','Gross desk-hours per week')+metric('availableDeskHours','Bookable desk-hours per week')+metric('usedDeskHours','Scenario booked desk-hours')+metric('memberEquivalents','Weekly member equivalents'),'Activity area = indoor envelope × (1 − support share).<br>Desk-hours = desks × hours × days × availability × booking share.<br>Member equivalents = booked desk-hours ÷ average hours per member.','Planning people are an area allowance, not an approved occupancy. The model does not establish a present room layout. Member equivalents are weekly use at the stated average, before actual booking peaks are resolved.'))
rf=''.join([field('rooms','Shared rooms',form='rooms'),field('peoplePerSession','People per session',form='rooms'),field('openHours','Opening hours per day',step='.5',maximum=24,form='rooms'),field('openDays','Opening days per week',maximum=7,form='rooms'),field('availabilityPercent','Bookable availability · %',maximum=100,form='rooms'),field('bookingPercent','Use of bookable time · %',maximum=100,form='rooms'),field('sessionHours','Session duration · hours',step='.25',minimum='.25',form='rooms'),field('turnoverMinutes','Setup and changeover · minutes',step='5',form='rooms')])
capacity+=section('Room-time calculator','Allow for the work between sessions.','<p class="lead narrow">Teaching, mentoring, meetings and rehearsals each use time around the activity. Compare the pooled weekly room-hour envelope, then check a real room-by-room calendar.</p>'+tool('rooms','Rooms, sessions and visits','An attendance is a visit. A returning learner can account for several visits.',rf,'wholeSessions','whole-session upper planning envelope per week',metric('grossRoomHours','Gross room-hours')+metric('availableRoomHours','Bookable room-hours')+metric('usedRoomHours','Scenario booked room-hours')+metric('sessionEquivalents','Session equivalents before rounding')+metric('weeklyVisits','Weekly attendances at stated group size'),'Session cycle = session duration + turnover minutes ÷ 60.<br>Whole sessions = floor(booked room-hours ÷ session cycle).<br>Visits = whole sessions × people per session.','Pooling room-hours is an upper planning envelope. A real timetable must fit each room’s individual windows, compatible uses and available hosts.'),ident='room-time')
capacity+=section('Interpret the result','Ask what is driving the number.',table(['Change','What to examine'],[('More opening hours','Which hours people will use, and how access and support are provided.'),('More people per session','The actual activity, room, equipment and supervision.'),('Less turnover','Whether setup, cleaning and handover still fit.'),('More member equivalents','Peak demand, preferred booking times and repeat attendance.'),('More reserved support space','Reception, circulation, toilets, storage, staff facilities and technical services.')])+ '<div class="actions">'+link('economics.html','Connect capacity with operating costs →','button')+link('guide.html','Prepare a reviewable site brief','button secondary')+'</div>','paper')
page('capacity.html','Capacity calculators','Count the space.<br><em>Then the time.</em>','Explore indoor planning area, desks, rooms, opening hours, sessions and attendance through editable scenarios.','five-horizons-hero',capacity,eyebrow='Planning laboratory · Capacity and shared use')

ef=''.join([field('premisesMonthly','Proposed premises contribution · A$/month',form='economics',note='Illustrative input, separate from the existing whole-property lease.'),field('staffFte','Paid staff · FTE',step='.25',form='economics'),field('loadedAnnualSalary','Loaded staff cost · A$/FTE/year',step='1000',form='economics',note='Include relevant employer costs in the chosen amount.'),field('otherAnnual','Other operating costs · A$/year',step='1000',form='economics'),field('capital','Initial setup capital · A$',step='1000',form='economics'),field('renewalYears','Annualisation period · years',minimum='1',form='economics',note='Simple planning reserve, separate from a finance repayment schedule.'),field('contractAnnual','Proposed programme income · A$/year',step='1000',form='economics',note='Scenario income; replace with the actual agreed amount.'),field('memberMonthly','Member contribution · A$/month',step='5',form='economics'),field('feePayingMembers','Members paying that contribution',form='economics',wide=True)])
economics=section('An editable operating scenario','Give each cost and income stream a home.','<p class="lead narrow">A shared establishment can combine provider contributions, commissioned programmes, memberships and other agreed funding. Compare those amounts with the people, premises and continuing service they support.</p><div class="callout"><p>The starting inputs below are illustrative scenario values. They describe neither a proposed lease offer nor committed funding. Keep the initial cash needed for setup visible alongside the annualised planning reserve.</p></div>'+toolbar()+tool('economics','Premises, people and proposed income','Ordinary financial records carry wages, services, equipment and premises costs.',ef,'fundingGapAnnual','annual funding gap under the stated assumptions',metric('premisesAnnual','Annual premises contribution')+metric('staffAnnual','Annual loaded staffing cost')+metric('operatingAnnual','Annual recurring operating costs')+metric('renewalAnnual','Annualised setup / renewal allowance')+metric('totalAnnual','Total annual planning requirement')+metric('incomeAnnual','Proposed annual income')+metric('memberAnnual','Member contributions within that income')+metric('breakEvenMembers','Total paying members to balance this scenario')+metric('surplusAnnual','Scenario surplus'),'Annual requirement = premises + staffing + other operations + setup capital ÷ chosen years.<br>Income = proposed programme income + members × monthly contribution × 12.<br>Gap = max(0, requirement − income).','A cash-flow forecast must also place deposits, setup payments, receipts and reserves in their actual months. Grants, debt, guarantees, in-kind support and service income have distinct effects.'))
lf=''.join([field('baseAnnual','Starting annual lease reference · A$',step='1000',form='lease'),field('increasePercent','Annual indexation · %',step='.1',form='lease'),field('year','Lease year to examine',minimum='1',maximum='50',form='lease'),field('term','Total term · years',minimum='1',maximum='50',form='lease')])
economics+=section('Existing lease reference','Keep the QPS commitment in its own account.','<p class="lead narrow">The CCC report records a starting annual lease figure of A$5.8 million, flat 4% annual indexation and a 15-year term. This reference calculator shows the arithmetic by lease year.</p>'+tool('lease','Lease year and indexed amount','Year 1 uses the starting amount. Each following year applies the stated increase.',lf,'monthly','monthly reference amount for the selected lease year',metric('annual','Annual reference amount')+metric('cumulativeTerm','Sum across the stated term'),'Annual amount in year n = base × (1 + rate)<sup>n−1</sup>.<br>Monthly reference = annual amount ÷ 12.<br>Term sum adds each indexed annual amount.','This reference is distinct from the amount a civic operator might agree to contribute. It does not establish a community tenancy, current invoice or sublease entitlement.')+source_line(link('https://www.ccc.qld.gov.au/sites/default/files/Docs/Publications/CCC/CCC-Public-Report_Investigation-Sphynx_Nov-2026.pdf','CCC Investigation Sphynx, November 2026, timeline entry at PDF page 21')+'.'),ident='lease-reference')
qf=''.join([field('nodes','Compute node equivalents',form='compute'),field('capitalPerNode','Initial installed allowance · A$/node',step='1000',form='compute'),field('ratedKw','Rated IT load · kW/node',step='1',form='compute'),field('utilisationPercent','Average IT utilisation · %',maximum='100',form='compute'),field('pue','Facility / IT power ratio',step='.05',minimum='1',form='compute',note='Illustrative multiplier for supporting power demand.'),field('electricityPerKwh','Electricity energy price · A$/kWh',step='.01',form='compute',note='Energy charge only; network, demand and other charges require their own cost lines.')])
economics+=section('Optional technical module','Compute needs its own workload and site case.','<p class="lead narrow">The Missing Middle plan uses A$6 million as an initial installed node allowance. Use this separate module to explore one technical scenario; it is not automatically added to the civic operating model.</p>'+tool('compute','Compute capital and energy','Rated IT power, average utilisation and facility overhead are separate inputs.',qf,'capital','initial infrastructure capital in this optional scenario',metric('totalPowerKw','Average facility load · kW')+metric('annualKwh','Annual energy · kWh')+metric('annualElectricity','Annual energy charge at stated rate'),'Average power = nodes × rated IT kW × utilisation × facility ratio.<br>Annual energy = average kW × 8,760 hours.<br>Energy charge = annual kWh × A$/kWh.','Site power, cooling, loading, handling, fibre and the actual workload determine the installation. This scenario uses authored planning assumptions rather than a specification or current supplier quote.')+source_line(link('https://auraofintelligence.github.io/installing-the-missing-middle/economics.html','Installing the Missing Middle: economics')+' · '+link('https://auraofintelligence.github.io/sovereign-capacity-lab/','Sovereign Capacity Lab')+'.'),ident='compute')
economics+=section('Different accounts, different purposes','Three A$6 million figures can mean different things.',table(['Figure','Basis','What belongs in this model'],[('Approximately A$6m a year','Rounded reference at A$500,000 a month for the whole property.','Use the lease-reference module for indexed amounts and dates.'),('A$6m initial capital','The authored installed-compute-node planning allowance.','A selected technical module with its own capital and operating case.'),('A$6m annual programme guide','500 Queens: A$5m enterprise grants plus A$1m incubator operations, using rounded 2021 inputs.','Update the local programme costs; keep enterprise grants separate from premises and staffing.')])+ '<p style="margin-top:1.5rem">C-Hour recognises voluntary human time. Community-chosen thanks and reciprocity sit alongside the financial accounts and the record of actual outcomes.</p>','paper')
page('economics.html','Costs and resources','Make the<br><em>numbers speak.</em>','Compare an illustrative operating model, the existing lease reference and an optional compute scenario, each in its own terms.','rooftop-solar',economics,eyebrow='Planning laboratory · Costs, income and shared resources')

workforce=section('Learning through work','Build capability that stays with people.','<div class="split"><div class="flow"><p class="lead">A civic establishment can connect practical work, mentoring, personal intelligence and the chance to teach someone else.</p><p>Ready SET Co-op links sustainable employment and training with shared equipment and local ownership. Try Everything Once explores different kinds of useful work, while Mutual Futures connects experienced businesses, succession and paid knowledge transfer.</p><p>These activities can share teaching rooms, a workshop, creative space and project desks. Hosts retain their own responsibilities for the work they offer and the people supporting it.</p></div>'+figure('tools-hero')+'</div>')
workforce+=section('The teacher-development route','Sixty learning days, with a chosen calendar.',table(['Learning connection','A useful studio output'],[('Personal Aura and meaningful records','A source-linked project, a correction and a teach-back for another learner.'),('Practical work and reflection','A mentored task, feedback and a record of what the person actually did.'),('Day 41: compute and a wellbeing hub','A workload card, physical dependency map, XR installation rehearsal and handover.'),('Day 42: distributed memory','An export, restoration exercise, permission map and continuation pack.'),('Civic and scientific development','A chosen question, evidence, a shared decision and an explanation someone else can examine.')])+ '<p class="table-note">The sixty-day teacher progression uses an individual learning calendar and different pacing. Teaching hours, attendance and staff availability are inputs for the local timetable.</p>'+source_line(link('https://auraofintelligence.github.io/aura-teacher-training/','Aura Teacher Training')+' · '+link('https://auraofintelligence.github.io/installing-the-missing-middle/learning.html','Installation learning and knowledge transfer')+'.'),'paper')
workforce+=section('Women directing enterprise','Leadership needs work, relationships and resources.','<div class="split align-top"><div class="flow"><p>500 Queens connects women developing as executives, enterprise leaders and decision makers with mentors, project work and backing. Shared desks can sit alongside bookable teaching, enterprise discussions and events.</p><p>The historical guide distinguishes women participating in leadership development, enterprises receiving grants and people appointed to executive roles. Those measures remain separate from daily desk demand.</p>'+link('https://auraofintelligence.github.io/500-Queens-VC-2026/','Explore 500 Queens →','text-link')+'</div><div class="panel"><p class="eyebrow">A repeatable learning record</p><h3>Observe. Rehearse. Do. Explain.</h3><p>Record the task, support, conditions, feedback and demonstrated work. The next experience can build on something specific.</p><p>Paid employment, supervised learning and voluntary contribution keep their actual terms and records.</p>'+link('capacity.html#room-time','Explore teaching-room time →','text-link')+'</div></div>')
workforce+=section('From one installation to the next','The place can support a delivery workforce.','<div class="prose"><p>The installation plan joins site surveys, equipment delivery, power and cooling, commissioning, learning capture, maintenance and renewal. A Brisbane hub could provide a meeting and rehearsal base for that work while installations occur at their own sites.</p><p>A digital twin, selected recordings and short learning material can preserve explanations from experienced trades and technical staff. Each lesson identifies the work and the qualifications, supervision or assessment relevant to carrying it out.</p><p>The delivery business, local operator, equipment owner and teaching partner can participate through separate agreements. A shared building helps them meet, practise and exchange knowledge.</p></div>')
page('workforce.html','Workforce and teaching','Learn it.<br>Build it.<br><em>Pass it on.</em>','Connect practical learning, mentoring, women’s enterprise and technical delivery through shared facilities.','people-practice-hero',workforce)

resilience=section('Everyday usefulness','Familiar places build readiness.','<div class="split"><div class="flow"><p class="lead">A space people use for ordinary learning and community life can also support preparedness, volunteer development and rehearsal.</p><p>The disaster-resilience proposal connects public information, personal support, maintained kiosks, practical learning and a visible next owner for a help request. A shared hub can host selected demonstrations and coordination work around those functions.</p><p>The local brief identifies the responsible organisations, actual receiving services and what the building is being asked to provide. Those relationships give an exercise or service a practical home.</p></div>'+figure('csiro-compute','Historical infrastructure reference: CSIRO GPU cluster, 19 April 2010. CSIRO, CC BY 3.0.')+'</div>')
resilience+=section('A complete experience to rehearse','Prepare, hand over, interrupt and restore.',panels([('Find a useful source','Practise checking who issued a notice, its date, audience and next action.','guide.html'),('Give a request a next owner','Distinguish local saving, delivery, acceptance, allocation and a recorded outcome.','network.html'),('Carry service through a change','Rehearse a lost connection, a relief handover, waiting work and restoration.','shared-use.html')]),'paper')
resilience+=section('Volunteering and support','Match willingness with a useful, supported role.','<div class="prose"><p>A participant might help explain information, prepare accessible material, look after equipment, organise a gathering or support a community project. The host connects that willingness with a task, support and a route for questions.</p><p>Volunteering Queensland’s Volunteer Management Activity supports volunteer-involving organisations. Its EV Crew programme connects councils and community organisations with people offering disaster-recovery help.</p><p>C-Hour can recognise verified voluntary human time, with locally chosen reciprocity. The programme’s money account pays for staff, equipment and operations; its outcome record describes what the work achieved.</p><div class="actions">'+link('https://volunteeringqld.org.au/initiatives/volunteer-management-activity-project/','Volunteer management resources','button secondary')+link('https://evcrew.volunteeringqld.org.au/for-volunteers','EV Crew','button secondary')+'</div></div>')
resilience+=section('A place-specific role','Develop the actual operating connection.',table(['Possible contribution','What makes the role concrete'],[('A demonstration and exercise centre','Named hosts, sample messages, a chosen scenario, a controller and recorded observations.'),('Volunteer learning and coordination','Actual roles, support, availability, expenses and handover arrangements.'),('A kiosk and continuity-kit workshop','Equipment inventory, maintenance, measured power demand and restoration practice.'),('Community recovery activity','An agreed service purpose, responsible provider, location and continuing support.')])+ '<div class="callout"><p>Designation as an evacuation centre or emergency facility is a separate site and operating decision. This exploration currently describes learning, readiness and selected community-support functions.</p></div>'+source_line(link('https://github.com/auraofintelligence/aura-disaster-resilience/wiki','Aura Disaster Resilience planning workshop')+' · '+link('https://www.brisbane.qld.gov.au/content/dam/brisbanecitycouncil/corpwebsite/about-council/documents/brisbane-city-council-local-disaster-management-plan.pdf.coredownload.pdf','Brisbane Local Disaster Management Plan')+'.'))
page('resilience.html','Resilience and contribution','Useful every day.<br><em>Ready to help.</em>','Develop preparedness, volunteer learning and continuity through familiar places and maintained relationships.','tools-hero',resilience)

access=section('KYC and a shared place','Know who is entering. Make the purpose clear.','<div class="split"><div class="flow"><p class="lead">The operating direction is 24/7 shared use with KYC, meaning identity verification appropriate to the facility relationship.</p><p>A membership account can establish who the person is. A permission identifies the spaces, equipment or activities available to them. A booking allocates time. The activity host carries the relevant service responsibilities.</p><p>Personal Aura records keep their own chosen audiences and permissions. Building access, a teaching portfolio and a private reflection each have a distinct purpose.</p></div><div class="panel"><p class="eyebrow">A policy to develop with people</p><h3>Identity → permission → booking → handover</h3><p>Agree what information the facility needs, who performs verification, who can review it, how long it is retained and how a person corrects an error or changes their access.</p><p>The examples below explore a future facility policy. This public planning site does not collect identity documents or issue building credentials.</p></div></div>')
access+=section('Explore an access scenario','The right relationship for the room.','<div class="access-scenario"><div class="input-grid"><label>Relationship to the facility<select data-access-person><option value="guest">Guest or first-time visitor</option><option value="member">Verified member</option><option value="host">Approved activity host</option><option value="technical">Authorised technical operator</option></select></label><label>Space to use<select data-access-space><option value="public">Welcome and public introduction</option><option value="desk">Shared desk</option><option value="quiet">Bookable quiet room</option><option value="workshop">Workshop activity</option><option value="compute">Restricted equipment room</option></select></label></div><div class="access-result" data-access-result aria-live="polite"><strong>A hosted introduction</strong><p>A guest can explore an introductory activity through the agreed welcome and host arrangements. Access to other spaces follows the selected activity and facility policy.</p></div></div><p class="table-note">Illustrative relationships for discussion. The future operator determines its actual access policy, verification process and service arrangements.</p>','paper')
access+=section('A few relationships to make understandable','Access should be easy to explain.',table(['Relationship','Possible arrangement to develop'],[('Guest','An understandable invitation, an identified host and a way to obtain assistance.'),('Verified member','Agreed identity checks, facility terms, an account recovery route and bookable access.'),('Activity host','Relevant room permissions, participant arrangements, setup and handover responsibilities.'),('Technical operator','Equipment-specific permissions, maintenance windows and an operating record.'),('Service provider','A defined service, its staffing and records, and the rooms needed for appointments or activities.')]))
access+=section('Dignity and continuity','People need a way through an error.','<div class="prose"><p>Verification can fail, a pass can be lost and a booking can change. The operating brief includes an assisted route, a responsible human contact, a review process and what happens outside ordinary reception hours.</p><p>A person should understand which part of the relationship is changing. A late booking, a service appointment and a technical permission have different consequences. Privacy-sensitive activity needs rooms and records appropriate to that activity.</p><p>A useful design tests the whole experience with participants: arrival, finding the room, understanding their activity, getting help and leaving the space ready for the next booking.</p>'+link('guide.html','Include access and handover in the site brief →','text-link')+'</div>')
page('access.html','KYC and access','Known people.<br><em>Clear access.</em>','Explore identity verification, activity permissions and bookings for a shared 24/7 facility.','start-here-hero',access)

local_cards='<div class="contact-row">'+''.join('<article class="panel"><p class="eyebrow">'+e(p['level'])+'</p><h3>'+e(p['name'])+'</h3><p>'+e(p['role'])+'</p><p>'+e(p['area'])+'</p><p>'+link('mailto:'+p['email'],e(p['email']))+'<br>'+e(p['phone'])+'</p>'+link(p['url'],'Official profile ↗','text-link')+'</article>' for p in partners['local'])+'</div>'
