partnerbody=section('Local representatives','Three useful routes into a place-based conversation.','<p class="lead narrow">The candidate site sits in Coorparoo Ward, the Greenslopes state electorate and the Griffith federal electorate. These public offices can help connect local questions with the relevant government responsibilities.</p>'+local_cards)
partnerbody+=section('Potential portfolio alignment','Connect a defined activity with the right responsibility.','<p class="lead narrow">This map identifies relevant responsibilities for a proposal. Its inclusion here describes potential alignment, rather than an existing endorsement, agreement or funding commitment.</p>'+table(['Theme and sources','Brisbane City Council','Queensland','Commonwealth'],portfolio_rows)+'<p class="table-note">Checked 7 November 2026. Amanda Stoker was appointed to the families and child-safety portfolios on 24 October 2026. Use the linked official pages to confirm details before an approach.</p>')
partnerbody+=section('A concrete first discussion','Bring the activity and the space into the same brief.',panels([('Premises and responsibilities','A proposed route into the building, the available indoor space, the parties and their responsibilities.','place.html'),('People and public value','A selected mix of activities, actual providers, intended participants and a result worth measuring.','overlaps.html'),('Resources and a working scenario','Room-hours, staffing, proposed contributions, equipment and a reviewable cost case.','economics.html')]),'paper')
page('partners.html','People and portfolios','Find the<br><em>right connection.</em>','Local representatives and relevant government portfolios for a practical, place-based proposal.','parliament-dusk',partnerbody)

guide_items=[
 ('purpose','A result worth pursuing','Name a useful outcome for the people who would use the place.'),
 ('mix','A selected combination','Choose the activities that gain something from sharing this location.'),
 ('rooms','An indoor room inventory','Record current dimensions, access, amenities, fit-out and supporting space.'),
 ('people','Actual people and responsibilities','Identify the host, operators, providers, participants and decision makers.'),
 ('calendar','A workable weekly calendar','Include preferred times, sessions, setup, cleaning, relief and maintenance.'),
 ('access','Identity and access arrangements','Develop verification, membership, guest access, permissions and assisted routes.'),
 ('equipment','Equipment and infrastructure','Connect each chosen workload with its equipment, power, data and upkeep.'),
 ('money','Costs, income and payment timing','Keep premises, staff, capital, grants, contracts, member contributions and reserves identifiable.'),
 ('tenure','A proposed premises arrangement','Record the space, term, activities, costs and responsibilities to discuss with the relevant parties.'),
 ('evidence','An experience to try and review','Choose a demonstration or use case and record what it will establish.')]
checklist='<div class="guide-grid">'+''.join(f'<article class="guide-card"><label><input type="checkbox" data-guide-check="{id}"><span><h3>{title}</h3><p>{text}</p></span></label></article>' for id,title,text in guide_items)+'</div>'
guide=section('A site brief people can examine','Put purpose, space and delivery on the same page.','<div class="split"><div class="flow"><p class="lead">A strong first brief describes a useful combination and shows how it could operate here.</p><p>Start with the people, their activity and the resource they share. Add a current room inventory, a weekly calendar and a transparent cost scenario. Identify the questions that belong to the property parties and those belonging to each service.</p><p>The brief can grow through demonstrations and real responses. It does not need to describe the whole Aura ecosystem before one useful overlap becomes understandable.</p></div>'+figure('public-decisions-hero')+'</div>')
guide+=section('Your working checklist','Track the parts you have brought together.','<p class="lead narrow">Mark a part when you have a useful starting record. The checklist stays in this browser and can be exported with its status.</p><p class="source-count" data-guide-count>0 of 10 parts marked</p><div class="progress-track" aria-hidden="true"><span data-guide-progress></span></div>'+checklist+'<div class="actions"><button type="button" class="button" data-guide-export>Export the checklist</button><button type="button" class="button secondary" data-print>Print this guide</button>'+link('downloads/site-brief-template.json','Download the site-brief template','button secondary')+'</div><p class="status" data-guide-status role="status" aria-live="polite"></p>')
guide+=section('A useful review pack','Four things to put in front of the next participant.',table(['Part','Contents'],[('The proposition','A chosen activity mix, intended people, public value and the reason this place helps.'),('The place','Current plan, room inventory, supporting facilities and the resource assumptions.'),('The operating scenario','Identity and booking arrangements, hosts, calendar, changeovers and continuing support.'),('The resource case','Separate initial capital, recurring costs, proposed income, contributions and unresolved inputs.')])+ '<div class="actions">'+link('overlaps.html','Choose an activity combination','button')+link('capacity.html','Save a capacity scenario','button secondary')+'</div>','paper')
page('guide.html','Build a site brief','From interest<br>to <em>a site brief.</em>','Bring a selected overlap, current room evidence and a working operating scenario into a reviewable proposal.','projects-hero',guide)

project_refs=[];seen=set()
for r in refs['sources']:
    if not r['id'].startswith(('D','W')):continue
    key=r.get('repository') or r['url'].replace('/index.html','/').rstrip('/')
    if key in seen:continue
    seen.add(key);project_refs.append(r)
network_cards='<div class="network-list">'+''.join('<article class="network-item"><h3>'+e(r['title'])+'</h3><p>'+e(r['note'])+'</p><div class="actions">'+link(r['url'],'Visit the public work ↗')+(link(r['repository'],'GitHub source ↗') if r.get('repository') else '')+'</div></article>' for r in project_refs)+'</div>'
network=section('A node with chosen connections','Keep the local place and the wider work in view.','<div class="split"><div class="flow"><p class="lead">The supplied material is one part of a much larger body of work. A Brisbane establishment can connect selected local activities with people, tools and knowledge elsewhere.</p><p>The Dunwich cultural-intelligence-node project explores a locally governed computing and collaboration setting on Minjerribah. The installation business develops a repeatable delivery and ownership pathway. Other projects bring learning, enterprise, care, culture, civic participation and science.</p><p>Connections follow the actual people, purposes and permissions involved. Each place can keep its own organisation, cultural relationships and priorities while sharing a useful method or agreed output.</p></div>'+figure('island-twin')+'</div>')
network+=section('Public project library','Follow the work at its own source.',network_cards)
network+=section('What travels between places','A useful result can leave more capability behind.',panels([('Learning and methods','A worked example, training material, a measured result and the correction that improved it.','workforce.html'),('Workloads and services','A defined compute job, a shared project or an agreed support relationship.','economics.html#compute'),('People and relationships','Mentors, peers, cultural collaboration and organisations choosing to work together.','partners.html')]),'paper')
page('network.html','Connected projects','One place.<br><em>A wider world.</em>','Follow the existing projects, source repositories and locally shaped relationships behind this exploration.','island-twin',network)

source_kinds=sorted({r['kind'] for r in refs['sources']})
source_items='<div class="source-list">'+''.join('<article class="source-item" data-source-item data-kind="'+e(r['kind'],quote=True)+'" data-search="'+e(' '.join([r['id'],r['title'],r['kind'],r['author'],r['note']]).lower(),quote=True)+'"><span class="pill">'+e(r['id'])+' · '+e(r['kind'])+'</span><h3>'+e(r['title'])+'</h3><p>'+e(r['author'])+' · '+e(r['date'])+'</p><p>'+e(r['note'])+'</p><div class="actions">'+link(r['url'],'Open public source ↗')+(link(r['repository'],'Repository ↗') if r.get('repository') else '')+'</div></article>' for r in refs['sources'])+'</div>'
sources=section('Evidence and authored direction','Keep the source and its meaning attached.','<p class="lead narrow">The starting library contains 17 supplied documents, four linked websites and four building-research references. Public links lead to the relevant project counterpart or source library; a counterpart may carry a later edition.</p><div class="grid-3" style="margin-top:2rem"><article class="panel"><h3>Building evidence</h3><p>Dated reports and plan records describe the property and the basis of each area or lease measure.</p></article><article class="panel"><h3>Authored proposals</h3><p>Luke Nathan Hayes’s project material supplies the intended functions, relationships and corrections.</p></article><article class="panel"><h3>Planning assumptions</h3><p>Editable numbers describe scenarios. They become local evidence through measured space, agreed services and observed use.</p></article></div><div class="source-filter"><label>Find a source<input type="search" data-source-query placeholder="Try teacher, building, C-Hour or women" autocomplete="off"></label><label>Source type<select data-source-kind><option value="">All types</option>'+''.join('<option>'+e(k)+'</option>' for k in source_kinds)+'</select></label></div><p class="source-count" data-source-count>'+str(len(refs['sources']))+' sources</p>'+source_items+'<p class="callout" data-source-empty hidden>No sources match these filters. Try a project title or clear the source type.</p>')
sources+=section('Interpretation and updates','Carry the correction forward.','<div class="prose"><p>The October installation plan preserves a federation of distinct organisations, finite investment arrangements, local ownership and ongoing renewal. Its current direction takes precedence over inconsistent archive wording.</p><p>The C-Hour planning edition’s correction register preserves community-chosen reciprocity while removing monetary conversion, wage substitution and financial-asset claims. The participant experience remains a proposal to develop through useful agent interactions and local pilots.</p><p>Building measurements and political responsibilities can change. Dates and links let a later review establish what needs updating. Original documents retain their history.</p><div class="actions">'+link('data/references.json','Public source catalogue · JSON','button secondary')+link('data/partners.json','Portfolio map · JSON','button secondary')+link('data/default-results.json','Default scenarios · JSON','button secondary')+'</div></div>','paper')
page('sources.html','Sources and assumptions','Follow the<br><em>source trail.</em>','A searchable catalogue of building evidence, authored proposals and the assumptions used in this first edition.','library-hero',sources)

style=section('A recognisable publishing pattern','Give the idea a clear visual home.','<div class="prose"><p>This site follows the established Aura project pattern: distinct photographic heroes, accessible reading, visible sources, full navigation, linked repositories and the Strange But True Public Source Licence.</p><p>Its own identity uses deep ink and cobalt with warm amber, cream and mint. The visual purpose is a welcoming civic place with practical technical capability and room for different lives.</p></div><div class="swatches">'+''.join('<div class="swatch"><i style="background:'+colour+'"></i><span>'+name+'<br>'+colour+'</span></div>' for name,colour in [('Ink','#091429'),('Cobalt','#3864ed'),('Amber','#f6ba54'),('Paper','#f3f0e7'),('Mint','#8cdbc1')])+'</div>')
style+=section('Words and evidence','Explain the task before adding the detail.',table(['Convention','Application'],[('Australian context','Australian English, AUD, metric units and the relevant public institutions.'),('An invitational voice','Describe useful possibilities, actual responsibilities and a result people can examine.'),('Clear evidence','Keep historical facts, authored directions, scenario assumptions and operating arrangements distinguishable.'),('Whole-person purpose','Learning, joy, care, agency, work and contribution can coexist across different personal paths.'),('Direct language','Use clear sentences, explain an initialism on first use and preserve uncertainty where it matters.')]),'paper')
style+=section('Images that mean what they show','Real places and imagined possibilities.','<div class="split"><div class="flow"><p>Every public page has a distinct hero. Photographs identify their real subject, creator and licence. Generated images describe imagined settings and keep their source prompts and tool metadata.</p><p>Images retain their native proportions in inline figures. Heroes adapt to the screen through a display crop. Captions stay outside the image so the evidence is readable.</p><p>Keyboard focus, reduced motion, mobile reading, printable guides and visible calculator units are part of the same visual system.</p>'+link('credits.html','Inspect the image register →','text-link')+'</div>'+figure('parliament-chamber')+'</div>')
style+=section('A maintainable public site','Keep content, formulas and discovery in step.','<div class="prose"><p>The page generator supplies complete navigation, previous and next routes, canonical addresses and both human and machine-readable sitemaps. The formulas live in a separate module with arithmetic checks.</p><p>The repository includes favicon sizes, a web manifest, source data, image provenance, AI transparency notes, robots.txt and llms.txt. A repository-path robots file points to origin-wide policy rather than claiming control of the whole GitHub Pages domain.</p><div class="actions">'+link(REPO,'Read the source repository','button secondary')+link('AI-TRANSPARENCY.md','AI transparency notes','button secondary')+link('robots.txt','robots.txt','button secondary')+link('llms.txt','llms.txt','button secondary')+'</div></div>')
page('style-guide.html','Style guide','A clear place<br>for <em>the idea.</em>','The visual, editorial and publishing conventions behind the civic establishment site.','global-festival',style)

credit_items='<div class="credits-grid">'
for slug,im in images.items():
    source=im.get('source_url') or im.get('source') or im.get('source_project','')
    licence_url=im.get('licence_url') or 'LICENCE.md'
