credit_items+='</div>'
credits=section('Every image has a source','Photographs keep their own rights.','<p class="lead narrow">This edition uses both new generated concepts and documented artwork and photographs from the existing project library. Each photograph retains its original licence, including attribution and share-alike conditions where applicable.</p><p class="narrow">Concept scenes illustrate possibilities. Captions identify real photographic locations. Image use here does not identify a government partnership, actual participants or a completed fit-out.</p><div class="actions">'+link('data/images.json','Image register · JSON','button secondary')+link('data/generated-image-provenance.json','New concept prompts · JSON','button secondary')+'</div>'+credit_items)
page('credits.html','Images and provenance','Know what<br><em>you are seeing.</em>','Creators, sources, licences and generation records for the site’s heroes and inline images.','earth-at-night',credits)

licence_md=(R/'LICENCE.md').read_text(encoding='utf-8')
license_html=[];paragraph=[];in_list=False
def flush_paragraph():
    if paragraph:license_html.append('<p>'+e(' '.join(paragraph))+'</p>');paragraph.clear()
for line in licence_md.splitlines():
    if not line.strip():
        flush_paragraph()
        if in_list:license_html.append('</ul>');in_list=False
    elif line.startswith('#'):
        flush_paragraph();level=min(3,line.count('#')+1);license_html.append(f'<h{level}>'+e(line.lstrip('# '))+f'</h{level}>')
    elif line.startswith('- '):
        flush_paragraph()
        if not in_list:license_html.append('<ul>');in_list=True
        license_html.append('<li>'+e(line[2:])+'</li>')
    else:paragraph.append(line)
flush_paragraph()
if in_list:license_html.append('</ul>')
licence=section('Original work and third-party rights','Strange But True Public Source Licence.','<div class="licence-copy">'+''.join(license_html)+'</div><div class="actions">'+link('LICENCE.md','Read the licence file','button secondary')+link('RIGHTS.md','Rights and provenance notes','button secondary')+link('credits.html','Third-party image credits','button secondary')+'</div>')
page('licence.html','Licence and rights','Read. Learn.<br><em>Keep the credit.</em>','The full Strange But True Public Source Licence, with separate rights for photographs and other third-party material.','parliament-chamber',licence)

